-- tools/run.sh --flavour forever tools/coefscheck.lua
--
-- T132 (docs/tasks/T132-forever-coefficients.md): Forever's +bonus estimate
-- from talentsforever's per-rank coefficients (Data/Coefs_Forever.lua,
-- generated by tools/buildcoefs.py; PRELIMINARY until verified in game).
--
--   1. the data file's shape: every row's numbers positive and finite, a name;
--      the druid's ranks below all present
--   2. through the real Book on the stub, the author's export (2026-10-23):
--      Rejuvenation R1-R4 0.80 each (20% x 4 ticks, 3 s assumed); Healing
--      Touch R1-R4 0.429 / 0.571 / 0.714 / 0.857; Regrowth R2 0.286 + 0.071 x
--      7; Wrath R1 0.429; Moonfire R1 0.15 + 0.13 x 3 -- no sub-20 factor
--   3. a parsed tick period is used, not the 3 s assumption; a channel counts
--      its own ticks; the group rule still halves
--   4. an id with no row falls back to the old rule with its old words
--   5. a measured share still wins over the generated estimate
HARNESS_FLAVOUR = "forever"

local here = arg[0]:match("^(.*)/[^/]+$")

local ok, fails = 0, {}
local function check(name, cond, detail)
    if cond then ok = ok + 1 else fails[#fails + 1] = name .. (detail and (" - " .. detail) or "") end
    print(string.format("%-72s %s%s", name, cond and "ok" or "FAIL", detail and (" - " .. detail) or ""))
end
local function T(name, fn)
    local good, cond, detail = pcall(fn)
    if not good then check(name, false, "raised: " .. tostring(cond)) return end
    check(name, cond == true, detail)
end

local a0 = arg[0]; arg[0] = here .. "/harness.lua"
local ST = dofile(here .. "/harness.lua")
arg[0] = a0

local S = _G.STUB
local Book = ST.Book
local Coef = ST.Coefficients

local function Near(a, b) return type(a) == "number" and type(b) == "number" and math.abs(a - b) < 1e-9 end

-- The author's ranks, with the real ids and the beta client's texts
-- (talentsforever's `d`, level 60, no gear). 774, 1058, 5185 and 5176 are the
-- stub's own.
S.AddSpell(1430, "Rejuvenation", "Rank 3", function() return "Heals the target for 92 over 12 sec." end,
    { cast = 0, cost = 75, level = 16, base = 774 })
S.AddSpell(2090, "Rejuvenation", "Rank 4", function() return "Heals the target for 128 over 12 sec." end,
    { cast = 0, cost = 105, level = 22, base = 774 })
S.AddSpell(5186, "Healing Touch", "Rank 2", function() return "Heals a friendly target for 94 to 118." end,
    { cast = 2000, cost = 55, level = 8, base = 5185 })
S.AddSpell(5187, "Healing Touch", "Rank 3", function() return "Heals a friendly target for 188 to 232." end,
    { cast = 2500, cost = 110, level = 14, base = 5185 })
S.AddSpell(5188, "Healing Touch", "Rank 4", function() return "Heals a friendly target for 338 to 412." end,
    { cast = 3000, cost = 190, level = 20, base = 5185 })
S.AddSpell(8938, "Regrowth", "Rank 2", function()
    return "Heals a friendly target for 165 to 187 and another 154 over 21 sec." end,
    { cast = 2000, cost = 125, level = 18 })
S.AddSpell(8921, "Moonfire", "Rank 1", function()
    return "Burns the enemy for 9 to 11 Arcane damage and then an additional 12 Arcane damage over 9 sec." end,
    { cast = 0, cost = 25, level = 4 })
-- an id with no row: a Healing Touch rank under an id the export does not carry
S.AddSpell(95185, "Healing Touch", "Rank 5", function() return "Heals a friendly target for 510 to 616." end,
    { cast = 3500, cost = 280, level = 26, base = 5185 })

Book:MarkDirty()
local book = Book:Get()

local function Bonus(id)
    local e = book.spells[id]
    return e and e.bonus, e
end

--------------------------------------------------------------------------------
-- 1: the data file
--------------------------------------------------------------------------------
T("1 ST.CoefRules: every number positive and finite, every row named", function()
    local R = ST.CoefRules
    if type(R) ~= "table" then return false, "no ST.CoefRules" end
    local bad, n = {}, 0
    for id, r in pairs(R) do
        n = n + 1
        local where = tostring(id)
        if type(id) ~= "number" or id <= 0 or id ~= math.floor(id) then bad[#bad + 1] = where .. " id" end
        if type(r) ~= "table" then
            bad[#bad + 1] = where .. " row"
        else
            if r.direct == nil and r.tick == nil then bad[#bad + 1] = where .. " no share" end
            for _, k in ipairs({ "direct", "tick" }) do
                local v = r[k]
                if v ~= nil and (type(v) ~= "number" or v ~= v or v <= 0 or v == math.huge) then
                    bad[#bad + 1] = where .. " " .. k
                end
            end
            if type(r.name) ~= "string" or r.name == "" then bad[#bad + 1] = where .. " name" end
            if r.rank ~= nil and (type(r.rank) ~= "number" or r.rank < 1) then bad[#bad + 1] = where .. " rank" end
        end
    end
    return n > 0 and #bad == 0, n .. " rows; " .. table.concat(bad, "; ")
end)

T("1 the druid's ranks are there", function()
    local R = ST.CoefRules or {}
    local want = { 774, 1058, 1430, 2090, 5185, 5186, 5187, 5188, 8936, 8938, 8939, 5176, 8921 }
    local missing = {}
    for _, id in ipairs(want) do
        if type(R[id]) ~= "table" then missing[#missing + 1] = tostring(id) end
    end
    return #missing == 0, "missing " .. table.concat(missing, ", ")
end)

--------------------------------------------------------------------------------
-- 2: the author's export through the book
--------------------------------------------------------------------------------
for _, id in ipairs({ 774, 1058, 1430, 2090 }) do
    T("2 Rejuvenation " .. id .. ": 0.80 (20% x 4 ticks, 3 s assumed)", function()
        local b = Bonus(id)
        return b and b.from == "estimated" and Near(b.counts, 0.8)
            and b.why == "20% x 4 ticks, 3 s ticks assumed (talentsforever)",
            string.format("counts=%s why=%s", tostring(b and b.counts), tostring(b and b.why))
    end)
end

for id, want in pairs({ [5185] = { 0.429, "42.9%" }, [5186] = { 0.571, "57.1%" },
    [5187] = { 0.714, "71.4%" }, [5188] = { 0.857, "85.7%" } }) do
    T("2 Healing Touch " .. id .. ": " .. want[1], function()
        local b = Bonus(id)
        return b and b.from == "estimated" and Near(b.counts, want[1]) and b.why == want[2] .. " (talentsforever)",
            string.format("counts=%s why=%s", tostring(b and b.counts), tostring(b and b.why))
    end)
end

T("2 Regrowth R2: 0.286 + 0.071 x 7", function()
    local b = Bonus(8938)
    return b and b.from == "estimated" and Near(b.counts, 0.286 + 0.071 * 7)
        and b.why == "28.6% + 7.1% x 7 ticks, 3 s ticks assumed (talentsforever)",
        string.format("counts=%s why=%s", tostring(b and b.counts), tostring(b and b.why))
end)

T("2 Wrath R1: 0.429, no sub-20 factor", function()
    local b = Bonus(5176)
    return b and b.from == "estimated" and Near(b.counts, 0.429) and b.why == "42.9% (talentsforever)",
        string.format("counts=%s why=%s", tostring(b and b.counts), tostring(b and b.why))
end)

T("2 Moonfire R1: 0.15 + 0.13 x 3", function()
    local b = Bonus(8921)
    return b and b.from == "estimated" and Near(b.counts, 0.15 + 0.13 * 3)
        and b.why == "15% + 13% x 3 ticks, 3 s ticks assumed (talentsforever)",
        string.format("counts=%s why=%s", tostring(b and b.counts), tostring(b and b.why))
end)

--------------------------------------------------------------------------------
-- 3: the tick period, a channel, the group rule (Coef.Estimate on its own)
--------------------------------------------------------------------------------
T("3 a parsed tick period is used: 2 s over 10 s is 5 ticks", function()
    local id = 774
    local e = { id = id, dur = 10, parsed = { heal = { tick = 20, period = 2, periodDur = 10 } } }
    local c, why = Coef.Estimate(e, "hot", "heal")
    return Near(c, 0.2 * 5) and why == "20% x 5 ticks (talentsforever)", tostring(c) .. " " .. tostring(why)
end)

T("3 a channel counts its own ticks (duration / period)", function()
    local saved = ST.CoefRules[99001]
    ST.CoefRules[99001] = { tick = 0.1, name = "Test Channel", rank = 1 }
    local e = { id = 99001, castKind = "channeled", interval = 8,
        parsed = { heal = { tick = 50, period = 2, periodDur = 8 } } }
    local c, why = Coef.Estimate(e, "hot", "heal")
    ST.CoefRules[99001] = saved
    return Near(c, 0.4) and why == "10% x 4 ticks (talentsforever)", tostring(c) .. " " .. tostring(why)
end)

T("3 the group rule still halves", function()
    local e = { id = 5185, targets = "party", parsed = { heal = { min = 40, max = 54 } } }
    local c, why = Coef.Estimate(e, "direct", "heal")
    return Near(c, 0.429 * Coef.GROUP) and why == "42.9% (talentsforever), group rule", tostring(c) .. " " .. tostring(why)
end)

T("3 a tick row with no duration gives no share", function()
    local c, why = Coef.Estimate({ id = 774, parsed = { heal = { min = 1, max = 2 } } }, "hot", "heal")
    return c == nil and why == "no duration", tostring(c) .. " " .. tostring(why)
end)

--------------------------------------------------------------------------------
-- 4: no row, the old rule
--------------------------------------------------------------------------------
T("4 an id with no row: the old rule and its words", function()
    local b = Bonus(95185)
    -- cast 3.5 / 3.5, level 26 (no sub-20 factor); the stub has no C_Traits,
    -- so Healing Touch's Naturalist rule says the talents were not read
    return ST.CoefRules[95185] == nil and b and b.from == "estimated" and Near(b.counts, 1)
        and b.why == "cast 3.5 / 3.5 (talents not read)",
        string.format("counts=%s why=%s", tostring(b and b.counts), tostring(b and b.why))
end)

T("4 the old rule by Coef.Estimate: no id, Classic's words", function()
    local c, why = Coef.Estimate({ dur = 12, level = 4 }, "hot")
    return Near(c, 12 / 15 * (1 - 16 * 0.0375)) and why == "over 12 s / 15 x 0.40", tostring(c) .. " " .. tostring(why)
end)

--------------------------------------------------------------------------------
-- 5: a measured share wins
--------------------------------------------------------------------------------
T("5 a narrow measured share wins over the generated estimate", function()
    ST.cdb.bonusCounts = ST.cdb.bonusCounts or {}
    ST.cdb.bonusCounts[1430] = { v = 2, points = { { 0, 92 }, { 100, 156 } }, counts = 0.64,
        lo = 0.63, hi = 0.65, at = 12345, bonus = 100 }
    Book:MarkDirty()
    local e = Book:Get().spells[1430]
    local b = e and e.bonus
    ST.cdb.bonusCounts[1430] = nil
    Book:MarkDirty()
    local after = Book:Get().spells[1430].bonus
    return b and b.from == "measured" and Near(b.counts, 0.64) and after.from == "estimated" and Near(after.counts, 0.8),
        string.format("from=%s counts=%s after=%s", tostring(b and b.from), tostring(b and b.counts), tostring(after and after.from))
end)

print(string.format("\n%d ok, %d failed", ok, #fails))
os.exit(#fails > 0 and 1 or 0)
